cat > /workspace/ghx_f2p_test.go <<'GHXEOF'
//go:build go1.23

package chi

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// Hidden F2P migration test (ADR-0032.1 S4). After migrating chi to Go 1.23's
// http.Request.Pattern, the matched route pattern must be published on
// r.Pattern for handlers.
func TestGHXRequestPatternPublished(t *testing.T) {
	var got string
	r := NewRouter()
	r.Handle("GET /hubs/{hubID}", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		got = req.Pattern
	}))
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/hubs/392", nil)
	r.ServeHTTP(rec, req)
	if got != "/hubs/{hubID}" {
		t.Fatalf("r.Pattern = %q, want /hubs/{hubID}", got)
	}
}
GHXEOF
